// The rebuilt league's clubs (spec O38 §5, §16): every real club in the eight-division pyramid, the
// outside pool, and Brabo's Antwerp neighbours, with facts, abilities, lore and congress seats.
// Generated by `Football shared/league/build_world.py` into world.json: edit the generator, not the output.
// The game does not load this file yet; LG-4 switches it over. Brabo United and the Old Selves are not
// in it: they stay in league.json and are added by the league rules.
import type { AbilityDef } from './load';
import type { AxisValues } from '../types';
import world from './world.json';

/** 1 = the Crown League … 8 = Division Eight. */
export type Division = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;
/** pyramid: one of the 94 in a division; pool: waits outside (continental cup, Big Cup, fills gaps); neighbour: a story club, never rated into the league. */
export type WorldPlace = 'pyramid' | 'pool' | 'neighbour';
/** Brabo's real Antwerp neighbours: the legend rival (was Antigoon FC) and the landlords (was Zurenborg Athletic). */
export type WorldRole = 'rival' | 'landlords';
export type StyleId = 'press' | 'possession' | 'low-block' | 'direct' | 'counter' | 'grit' | 'flair' | 'chaos';

/** Same values as `OwnerKind` on feat/congress (content/desk/types.ts). */
export type OwnerKind =
  | 'fan-owned' | 'state-fund' | 'old-family' | 'data-company' | 'billionaire' | 'investment-fund'
  | 'works-team' | 'celebrity' | 'municipal' | 'old-self';
/** feat/congress's regions, plus the new ones listed in `WorldData.newRegions` (needed for clubs outside its countries). */
export type RegionId =
  | 'flanders' | 'netherlands' | 'london' | 'north-england' | 'south-england' | 'wales'
  | 'castile' | 'catalonia' | 'basque' | 'andalusia' | 'spain-east' | 'spain-north' | 'canaries'
  | 'bavaria' | 'rhine-ruhr' | 'germany-north' | 'germany-east' | 'germany-south-west'
  | 'italy-north' | 'italy-centre-south' | 'paris' | 'france-south' | 'france-north' | 'rhone-alps'
  | 'alps-danube' | 'nordic' | 'portugal' | 'memory'
  | 'brussels' | 'france-west' | 'scotland' | 'greece' | 'turkiye' | 'central-europe' | 'balkans';
/** Same shape as `ClubSeat` on feat/congress, so `SEATS[id] = club.seat` joins it. */
export interface WorldSeat { owner: OwnerKind; region: RegionId }
export interface WorldRegion { id: RegionId; name: string; country: string; pride: string }

/**
 * The fogged club page. `manager`, `history` and `hiddenTease` have the shape of `ClubLore` in
 * content/desk/types.ts (managers are invented, as there: this world has its own dugouts).
 * `lines` are true facts from the club's real history: a founding story, a famous night, the ground,
 * a rivalry, a nickname's origin. Revealed one at a time as the fog lifts.
 */
export interface WorldLore {
  manager: { name: string; nation: string; line: string };
  history: string;
  hiddenTease: string;
  lines: string[];
}

export interface WorldClub {
  /** Kept from league.json or continental.ts where the club already exists; otherwise new and short. */
  id: string;
  name: string;
  short: string;
  nickname: string;
  city: string;
  /** Two-letter code as league.json uses them (EN, SC, WA for the home nations). */
  country: string;
  ground: string;
  founded: number;
  /** Primary, secondary, as hex. */
  colours: string[];
  style: StyleId;
  /** One or two, in the ability format of league.json (`AbilityDef`). */
  known: AbilityDef[];
  hidden: AbilityDef;
  /** Engine numbers from rating and style, as build_league.py's `engine()` computes them. */
  shrinks: Partial<AxisValues>;
  presses: Partial<AxisValues>;
  /** Game rating. In the pyramid: the draft's rating (104 → 62 by rank) clipped into its division's band. */
  rating: number;
  place: WorldPlace;
  /** Starting division; null outside the pyramid. */
  division: Division | null;
  /** 1-based order of strength across the whole file (pyramid first, then pool, then neighbours). */
  order: number;
  /** The source row in the Opta Power Rankings of 13 Nov 2026; null for a club the ranking does not hold. */
  opta: { name: string; rank: number; rating: number } | null;
  /** Where the id came from: an existing real club in league.json, a club abroad in continental.ts, or new. */
  was: 'league' | 'continental' | 'new';
  role?: WorldRole;
  lore: WorldLore;
  seat: WorldSeat;
}

export interface WorldData {
  note: string;
  source: string;
  divisionNames: Record<string, string>;
  /** Spec §5 bands, inclusive. */
  bands: Record<string, [number, number]>;
  /** How many places each division leaves for Brabo and the Old Selves at the start (Division Three: Brabo; Division Eight: AFC October 2026). */
  openPlaces: Record<string, number>;
  newRegions: WorldRegion[];
  clubs: WorldClub[];
}

export const WORLD = world as unknown as WorldData;
export const WORLD_CLUBS: WorldClub[] = WORLD.clubs;
export const worldClub = (id: string) => WORLD_CLUBS.find((c) => c.id === id);
